import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"RFC 0072 — External OAuth/OIDC provider for non-plugin apps","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0072-external-oauth-provider.md"},"headers":[],"relativePath":"rfcs/0072-external-oauth-provider.md","filePath":"rfcs/0072-external-oauth-provider.md"}'),n={name:"rfcs/0072-external-oauth-provider.md"};function s(r,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="rfc-0072-—-external-oauth-oidc-provider-for-non-plugin-apps" tabindex="-1">RFC 0072 — External OAuth/OIDC provider for non-plugin apps <a class="header-anchor" href="#rfc-0072-—-external-oauth-oidc-provider-for-non-plugin-apps" aria-label="Permalink to &quot;RFC 0072 — External OAuth/OIDC provider for non-plugin apps&quot;">​</a></h1><p><strong>Status:</strong> Implemented<br><strong>Date:</strong> July 2026<br><strong>Author:</strong> External contributor (submitted for consideration; adapted to repository conventions and revised during implementation against the actual <code>@better-auth/oauth-provider</code> API)<br><strong>Scope:</strong> <code>apps/auth</code>, <code>runtime</code> (better-auth client version only), <code>plugins/console</code>, <code>docs/self-hosting.md</code>, <code>docs/security.md</code>, <code>docs/upgrade.md</code>. Builds on RFC 0021 (platform roles &amp; capabilities).<br><strong>Incorporated into plan:</strong> Yes — epic tasks 1.18, 1.24 (addendum, partial).</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Let a Sovereign instance&#39;s auth server (<code>apps/auth</code>, a better-auth instance) act as an OAuth 2.0 / OIDC identity provider for applications that are <strong>not</strong> Sovereign plugins — standalone apps on their own domain and infrastructure that want &quot;log in with Sovereign&quot; without being composed into the Sovereign runtime, sharing its database, or joining the plugin manifest system.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Sovereign&#39;s plugin model assumes an app is composed into the platform monorepo at build time and reads its session via runtime-injected headers (<code>sdk.auth.getSession()</code>). That serves apps that want to live inside a Sovereign workspace, but not an adjacent, increasingly common case: an independent site on its own domain that simply wants to let a known set of people (already Sovereign users) sign in, without becoming a plugin.</p><p>This gap is concrete, not hypothetical: a separate standalone app under active development wants exactly this — sign-in backed by an operator&#39;s Sovereign instance, with its own independent authorization model (e.g. a curator allowlist) layered on top of verified identity.</p><p>better-auth ships provider support for exactly this. <strong>Important correction found during implementation:</strong> the originally-drafted target, the bundled <code>oidc-provider</code> plugin (<code>better-auth/plugins/oidc-provider</code>), is marked <code>@deprecated</code> as of the better-auth version this repo already pinned (1.6.16) — &quot;Use <code>@better-auth/oauth-provider</code> instead. This plugin will be removed in the next major version.&quot; better-auth split OAuth/OIDC provider support into a separate, actively-maintained package, <a href="https://www.better-auth.com/docs/plugins/oauth-provider" target="_blank" rel="noreferrer"><code>@better-auth/oauth-provider</code></a>. This RFC and its implementation build on that package instead — the gap is still &quot;not enabled, documented, or given a registration flow,&quot; not cryptographic or architectural.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><code>apps/auth/src/auth.ts:195-208</code> (<code>buildOptions()</code>, before this RFC) configured exactly three better-auth plugins: <code>twoFactor</code>, <code>passkey</code>, and <code>nextCookies</code>. No OIDC/OAuth provider plugin was enabled.</li><li><code>@better-auth/oauth-provider</code> manages its <strong>own</strong> schema (<code>oauthClient</code>, <code>oauthAccessToken</code>, <code>oauthRefreshToken</code>, <code>oauthConsent</code>) through better-auth&#39;s own adapter — unlike the hand-rolled <code>invites</code> table (<code>apps/auth/src/db.ts</code>&#39;s <code>ensureAuthTables()</code>), this schema is <strong>auto-discovered by better-auth&#39;s own migrator</strong> (<code>getMigrations()</code>/<code>runMigrations()</code> in <code>apps/auth/src/migrate.ts</code>, which RFC 0012 already documented as auto-discovering plugin tables for <code>twoFactor</code>/<code>passkey</code>). <strong>No custom table or migration code was needed</strong> — this corrects the original draft&#39;s assumption of a custom <code>ensureAuthTables()</code>-based client table.</li><li>The package exposes full client CRUD over HTTP, session-gated via its own <code>clientPrivileges</code> hook (<code>create</code>/<code>read</code>/<code>update</code>/<code>delete</code>/<code>list</code>/<code>rotate</code> actions) — <code>POST /oauth2/create-client</code>, <code>GET /oauth2/get-clients</code>, <code>POST /oauth2/client/rotate-secret</code>, <code>POST /oauth2/delete-client</code>. (Its <code>adminCreateOAuthClient</code>/<code>adminUpdateOAuthClient</code> variants are <code>SERVER_ONLY</code> — not HTTP-reachable at all — so the session-gated non-admin-prefixed endpoints are what a browser-facing Console UI must use, with <code>clientPrivileges</code> doing the actual authorization.)</li><li><code>storeClientSecret: &#39;hashed&#39;</code> is a first-class plugin option — no need to reinvent RFC 0043&#39;s &quot;generate once, store hashed&quot; discipline; the plugin already does it when configured this way.</li><li>The existing generic proxy <code>runtime/app/api/auth/[...path]/route.ts</code> (forwards <code>/api/auth/*</code> from the runtime&#39;s origin to the auth server with cookies + <code>Origin</code> header) already covers every path this plugin mounts — <strong>no runtime proxy changes were needed</strong> for the Console UI to reach these endpoints with the calling admin&#39;s real session.</li><li>RFC 0021 establishes platform roles/capabilities; <code>runtime/src/capabilities.ts</code>&#39;s <code>instance:configure</code> capability (granted to <code>platform:admin</code> and <code>platform:owner</code>) is reused for the Console page gate; <code>apps/auth</code> itself doesn&#39;t import runtime code, so its <code>clientPrivileges</code> role check (<code>platform:owner</code>/<code>platform:admin</code>) is a small, intentional duplication of the same role set.</li><li><code>docs/self-hosting.md</code> and <code>docs/security.md</code> had no section on external OAuth/OIDC before this RFC.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><ul><li>Making external apps first-class Sovereign plugins, or giving them access to <code>sdk.db</code>, <code>sdk.storage</code>, or any other plugin-scoped SDK surface. The only thing shared is verified identity (who is this person), not platform capabilities.</li><li>Changing how plugin-internal auth works today.</li><li>Any change to <code>sdk.auth.getSession()</code> or the plugin-facing session model.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="_1-enable-the-provider-plugin" tabindex="-1">1. Enable the provider plugin <a class="header-anchor" href="#_1-enable-the-provider-plugin" aria-label="Permalink to &quot;1. Enable the provider plugin&quot;">​</a></h3><p>Add <code>oauthProvider(...)</code> from <code>@better-auth/oauth-provider</code> to the <code>plugins</code> array in <code>buildOptions()</code> (<code>apps/auth/src/auth.ts</code>):</p><ul><li><code>loginPage: &#39;/login&#39;</code>, <code>consentPage: &#39;/oauth2/consent&#39;</code> (new page, §2b).</li><li><code>storeClientSecret: &#39;hashed&#39;</code> — secrets are never reversibly stored.</li><li><code>allowDynamicClientRegistration: false</code> (explicit — matches the plugin&#39;s own default; no self-service registration in v1).</li><li><code>clientPrivileges</code>: authorizes every client mutation (create/read/update/delete/list/rotate) only when the session user&#39;s <code>role</code> is <code>platform:owner</code> or <code>platform:admin</code>.</li></ul><h3 id="_2-client-registration-and-management" tabindex="-1">2. Client registration and management <a class="header-anchor" href="#_2-client-registration-and-management" aria-label="Permalink to &quot;2. Client registration and management&quot;">​</a></h3><p><strong>a. Console UI</strong> — a new &quot;External clients&quot; section (<code>plugins/console/app/oauth-clients/</code>), gated to <code>instance:configure</code> (granted to <code>platform:admin</code>/<code>platform:owner</code>), where an admin enters a display name and one or more exact redirect URIs. On submit the platform generates and displays a client ID and client secret exactly once (never shown again — only rotatable). The page calls the plugin&#39;s own non-admin-prefixed HTTP endpoints directly from the browser (<code>/api/auth/oauth2/create-client</code>, <code>/get-clients</code>, <code>/client/rotate-secret</code>, <code>/delete-client</code>) via the runtime&#39;s existing generic auth proxy — no new runtime or apps/auth routes were needed; <code>clientPrivileges</code> is the actual security boundary, re-checked by the plugin on every request regardless of what the Console page itself gates.</p><p><strong>b. Consent page</strong> — a new page at <code>apps/auth/app/oauth2/consent/</code>. The plugin&#39;s <code>/oauth2/authorize</code> redirects an already-authenticated user here with a signed query string; the page displays the requesting client&#39;s name and requested scopes (fetched from the plugin&#39;s public <code>/oauth2/public-client</code> endpoint) and, on Allow/Deny, POSTs to <code>/api/auth/oauth2/consent</code> with the signed query forwarded verbatim — the page never re-derives or trusts it, only displays and echoes it back for the plugin&#39;s own re-verification.</p><p><strong>c. Storage</strong>: entirely the plugin&#39;s own schema (<code>oauthClient</code>/<code>oauthAccessToken</code>/<code>oauthRefreshToken</code>/<code>oauthConsent</code>), auto-migrated — no custom table.</p><h3 id="_3-discovery-and-verification-endpoints" tabindex="-1">3. Discovery and verification endpoints <a class="header-anchor" href="#_3-discovery-and-verification-endpoints" aria-label="Permalink to &quot;3. Discovery and verification endpoints&quot;">​</a></h3><p>Exposed automatically by the plugin at the auth server&#39;s public URL:</p><ul><li><code>/.well-known/openid-configuration</code>, <code>/.well-known/oauth-authorization-server</code></li><li><code>/oauth2/authorize</code>, <code>/oauth2/token</code>, <code>/oauth2/userinfo</code></li><li><code>/.well-known/jwks.json</code> for offline signature verification</li></ul><p>Documented in <code>docs/self-hosting.md</code>&#39;s &quot;External OAuth/OIDC provider&quot; section and tracked in <code>docs/upgrade.md</code>.</p><h3 id="_4-claims-contract" tabindex="-1">4. Claims contract <a class="header-anchor" href="#_4-claims-contract" aria-label="Permalink to &quot;4. Claims contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Claim</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>sub</code></td><td>string</td><td>Stable user ID, same value across sessions</td></tr><tr><td><code>email</code></td><td>string</td><td>Verified email</td></tr><tr><td><code>name</code></td><td>string</td><td>Display name</td></tr></tbody></table><p>(The original draft proposed a <code>tenant</code> claim for multi-tenant operators; dropped — Sovereign is single-tenant per instance, so there is no tenant identifier to carry, and the plugin&#39;s <code>sub</code> is already scoped to this instance&#39;s own user table.)</p><p>Explicitly out of scope for v1: plugin capabilities, roles, or any Sovereign-internal authorization data. An external app treats this purely as &quot;who is this&quot; and manages its own authorization afterward (e.g. its own allowlist) — stated explicitly in <code>docs/self-hosting.md</code> so consumers don&#39;t conflate &quot;has a Sovereign account&quot; with &quot;authorized in my app.&quot;</p><h3 id="_5-trusted-origins-redirect-uri-allowlisting" tabindex="-1">5. Trusted origins / redirect URI allowlisting <a class="header-anchor" href="#_5-trusted-origins-redirect-uri-allowlisting" aria-label="Permalink to &quot;5. Trusted origins / redirect URI allowlisting&quot;">​</a></h3><p>Redirect URIs are matched <strong>exact-string only</strong> against the client&#39;s registered <code>redirect_uris</code> — the plugin&#39;s own behavior, no separate global config needed.</p><h3 id="_6-token-lifetime-and-refresh" tabindex="-1">6. Token lifetime and refresh <a class="header-anchor" href="#_6-token-lifetime-and-refresh" aria-label="Permalink to &quot;6. Token lifetime and refresh&quot;">​</a></h3><p>Left at the plugin&#39;s defaults (<code>accessTokenExpiresIn</code>, <code>refreshTokenExpiresIn</code>, <code>idTokenExpiresIn</code>, <code>codeExpiresIn</code>) — no reason found during implementation to diverge from them for v1.</p><h2 id="security-considerations" tabindex="-1">Security considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security considerations&quot;">​</a></h2><ul><li>Client secrets are shown exactly once and stored <strong>hashed</strong> (<code>storeClientSecret: &#39;hashed&#39;</code>) — never reversibly encrypted, never re-displayed after creation.</li><li>Redirect URI matching is exact-string only, to prevent open-redirect abuse.</li><li>Revoking a client (delete) immediately stops new token issuance for it; already-issued access tokens are left to expire naturally.</li><li>Registration/rotation/revocation is restricted to <code>platform:owner</code>/ <code>platform:admin</code> via <code>clientPrivileges</code> — there is no dynamic or self-service registration path to worry about in v1.</li><li>This surface increases the auth server&#39;s attack surface — it&#39;s now reachable by arbitrary external redirect targets, not just same-origin plugin routes. Reflected in <code>docs/security.md</code>&#39;s threat model table.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>The bundled <code>oidc-provider</code> plugin</strong> (<code>better-auth/plugins/oidc-provider</code>), the original draft&#39;s target: rejected once implementation began — it is <code>@deprecated</code> as of better-auth 1.6.16 (the version already pinned in this repo) in favor of <code>@better-auth/oauth-provider</code>, and &quot;will be removed in the next major version.&quot; Building new functionality on a plugin already flagged for removal would create near-term migration debt for no benefit; the replacement package required only a non-breaking <code>better-auth</code> dependency bump (<code>^1.6.16</code> → <code>^1.6.25</code>).</li><li><strong>Cross-subdomain cookie sharing</strong> (better-auth&#39;s <code>crossSubDomainCookies</code>): simpler to wire up, but couples the external app into the same auth realm/secret as the platform itself — a much larger trust and operational commitment than most external integrations want. Not proposed as the default path; worth documenting as a lighter-weight option for operators who explicitly want tighter coupling (e.g. a family of apps under one brand).</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><s>Should external client registration be admin-only, or delegable via the per-user capability grant mechanism (RFC 0070)?</s> <strong>Resolved:</strong> admin-only for v1 (<code>platform:owner</code>/<code>platform:admin</code> via <code>clientPrivileges</code>), consistent with the platform&#39;s operator-controlled trust model. Delegable via a grantable capability remains an option for a future task if needed.</li><li>Is per-client rate limiting needed on the token endpoint, separate from whatever protects plugin-internal auth today? Not addressed in v1 — left as a follow-up if abuse is observed.</li><li><s>Dynamic client registration vs. admin-registered only?</s> <strong>Resolved:</strong> admin-registered only for v1 (<code>allowDynamicClientRegistration: false</code>).</li></ul><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Implemented in epic task 1.18 as a single PR (provider plugin + consent page + Console registration UI + docs) — additive, no changes to existing auth flows. <code>better-auth</code> bumped <code>^1.6.16</code> → <code>^1.6.25</code> (non-breaking, same major) to meet <code>@better-auth/oauth-provider</code>&#39;s peer requirement.</p><h2 id="addendum-well-known-first-party-client-for-official-native-shells" tabindex="-1">Addendum: well-known first-party client for official native shells <a class="header-anchor" href="#addendum-well-known-first-party-client-for-official-native-shells" aria-label="Permalink to &quot;Addendum: well-known first-party client for official native shells&quot;">​</a></h2><p><strong>Status:</strong> Partially implemented (2026-08, epic task 1.24) — the seeding infrastructure below (points 1–3) is built and live; the shell-side consumer (§5&#39;s actual PKCE flow + OS keychain storage) is not, and remains genuinely unscheduled. RFC 0082 is now <strong>Accepted</strong> (<code>docs/rfcs/README.md</code>), but its own adoption path (epic tasks 2.27, 20.11, 20.12) doesn&#39;t include §5 — that stays a separate follow-up per RFC 0082 itself. Nothing in the shipped product consumes this yet; today&#39;s shells authenticate fine via plain WebView cookie sessions either way. The remaining open questions below (revocation semantics, Console visibility, the opt-out toggle) are still genuinely unresolved product decisions — don&#39;t guess at them; they matter more once a real shell-side consumer exists.</p><h3 id="motivation-1" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-1" aria-label="Permalink to &quot;Motivation&quot;">​</a></h3><p>v1&#39;s registration model (above) requires an admin to manually create a client in Console — a display name, an exact redirect URI, generated secret — before any external app can authenticate against that instance. That&#39;s the right model for its actual use case: a specific, known, deliberately-integrated third-party app on its own domain.</p><p>It&#39;s the wrong model for <code>sovereign-desktop</code> / <code>sovereign-mobile</code>. Those are <strong>universal shells</strong> — a single published binary that connects to whatever self-hosted instance a user types in, including one it has never talked to before. RFC 0082 §5 names this exact gap: &quot;A single published binary talking to arbitrary self-hosted instances would require every operator to hand-register a client in Console before login works — unacceptable for a store app.&quot; Today there is no way for either shell to become a registered OAuth client on a fresh instance without that instance&#39;s admin taking action first, which makes RFC 0082 §5&#39;s OS-keychain-backed durable session (and, transitively, sovereign-desktop epic task 17.4) unbuildable as sketched.</p><h3 id="proposed-design-1" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design-1" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h3><p><strong>Verified against the installed <code>@better-auth/oauth-provider@1.6.25</code> package</strong> (its <code>.d.mts</code> type definitions — the actual shipped API, not assumption). This corrected an earlier version of this draft, which proposed two fixed literal client IDs (e.g. <code>sovereign-desktop</code>) shared identically across every instance. That&#39;s not how the package works: <strong><code>adminCreateOAuthClient</code> never accepts a caller-supplied <code>client_id</code> — every client gets a server-generated ID, and there is no pluggable client-resolution hook to special-case a fixed one.</strong> The design below reflects what the package actually supports, not the original sketch.</p><ol><li><p><strong>Not implemented via <code>adminCreateOAuthClient</code> — corrected 2026-08, verified live, not assumed.</strong> The original draft claimed this endpoint was directly callable from server code because it&#39;s marked <code>SERVER_ONLY</code>. That&#39;s true of its HTTP-reachability, but its handler still calls <code>assertClientPrivileges</code>, which throws <code>UNAUTHORIZED</code> without a real user session (<code>getSessionFromCtx(ctx)</code>, checked against <code>clientPrivileges</code> in <code>apps/auth/src/auth.ts</code>) — and there is no session at server boot. <code>epic task 1.24</code> seeds the row via a direct <code>INSERT</code> into the <code>oauthClient</code> table instead (<code>apps/auth/src/builtin-oauth-clients.ts</code>), the same pattern <code>instrumentation.ts</code>&#39;s RFC 0021 owner-migration already uses for <code>better-auth</code>-owned tables. No patching or forking the package — the row shape (JSON-encoded array columns, boolean-as-0/1 on SQLite, <code>ON DELETE CASCADE userId</code> left <code>NULL</code>) was reverse-engineered from a client actually created through the legitimate <code>adminCreateOAuthClient</code> path with a genuine session, not guessed from the package&#39;s <code>.d.mts</code> types alone, and the seeded row was confirmed to resolve correctly through <code>getClient()</code> — the same internal resolver the real authorize flow uses.</p></li><li><p><strong>Implemented: seed one native, secretless, PKCE-required client per shell at auth server startup</strong>, idempotently — <code>apps/auth/instrumentation.ts</code> calls <code>seedBuiltinOAuthClients()</code> after migrations run, keyed on a stable value in the <code>name</code> column (doubles as the idempotency check) rather than <code>metadata</code>:</p><ul><li><code>sovereign-desktop</code> → <code>sovereign://oauth/callback</code> (epic task 17.3&#39;s existing scheme)</li><li><code>sovereign-mobile</code> → <code>sovereign://oauth/callback</code> — <strong>resolved</strong>: both shells register the identical <code>sovereign://</code> scheme (confirmed against <code>sovereign-mobile</code>&#39;s <code>Info.plist</code>/<code>AndroidManifest.xml</code>, added for deep linking, epic task 20.14). No collision risk despite the identical literal string — each is a distinct server-side client row scoped by its own <code>client_id</code>, and the two shells never coexist on the same OS.</li></ul><p>The resulting <code>client_id</code> is <strong>server-generated (a <code>randomUUID()</code>, not better-auth&#39;s own generator — its exact ID alphabet is an internal implementation detail this doesn&#39;t need to match) and different on every instance</strong> — there is no shared literal string. <code>cachedTrustedClients</code> is <strong>not used</strong> — left for the still-open revocation-semantics question below, since populating it now would prejudge that decision.</p></li><li><p><strong>Implemented: <code>GET /api/instance</code> now returns <code>oauthClients</code></strong> (<code>runtime/src/instance-oauth-clients.ts</code>, called from <code>runtime/app/api/instance/route.ts</code>) — a server-to-server call to a new public, unauthenticated <code>apps/auth</code> route, <code>GET /api/oauth-clients</code> (<code>apps/auth/app/api/oauth-clients/route.ts</code>), which re-seeds on read (cheap and idempotent) rather than trusting startup timing alone. Resolves the addendum&#39;s own &quot;upgrade window&quot; open question from below: an instance that hasn&#39;t seeded yet, or whose auth server is unreachable, gets the field <strong>omitted entirely</strong>, not an error — the shell already has to treat a missing field as &quot;not yet available&quot; for any older-platform-version instance, so no new case to handle.</p></li><li><p><strong>Redirect URI matching stays exact-string-only</strong>, per §5 above — each seeded client&#39;s redirect is exactly one value stored on its own <code>OAuthClient</code> row, so this doesn&#39;t loosen that rule at all; it&#39;s the same exact-match behavior every other client already gets.</p></li></ol><h3 id="security-considerations-1" tabindex="-1">Security considerations <a class="header-anchor" href="#security-considerations-1" aria-label="Permalink to &quot;Security considerations&quot;">​</a></h3><ul><li>No secret to leak, by design — the generated ID being discoverable via a public endpoint is the point of a PKCE public client, not a weakness introduced here.</li><li>The real security boundary is (a) PKCE <code>code_verifier</code> possession and (b) exact match against each instance&#39;s own stored <code>redirect_uri</code>. A malicious app that also registers the same custom scheme on the same device (a known risk class for native-app OAuth, historically worse on Android than iOS/macOS) could observe the authorization <em>code</em> via the redirect, but cannot complete the token exchange without the <code>code_verifier</code>, which never leaves the legitimate app&#39;s process. This narrows but does not fully eliminate scheme-hijacking risk — accepted residual risk consistent with mainstream native-app OAuth (RFC 8252), not a novel gap.</li><li><strong>Revised from an earlier version of this draft, which assumed one shared client ID trusted unconditionally by every instance:</strong> because each instance seeds and stores its <em>own</em> client independently (point 2), an operator can revoke it the same way as any other client — delete the row in Console (or, if <code>cachedTrustedClients</code> is used to protect it from accidental deletion, whatever un-cache/disable path that requires). A compromised official shell build is contained per-instance, not trusted everywhere until a platform-wide fix ships — a meaningfully better story than the original sketch, and worth noting as a reason this correction is an improvement, not just a complication. What doesn&#39;t change: nothing stops a compromised build from authenticating against any instance whose <em>user</em> still trusts it enough to run it and hasn&#39;t revoked access — that part is inherent to any first-party client model, not specific to this design.</li><li>Whether <code>cachedTrustedClients</code> (making the seeded client immutable through Console&#39;s CRUD) is worth trading against the revocability above is exactly the operator-control question the Alternatives section&#39;s opt-out toggle addresses — not resolved here.</li></ul><h3 id="alternatives-considered-1" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered-1" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h3><ul><li><strong>Fully dynamic client self-registration</strong> (<code>allowDynamicClientRegistration: true</code>), gated by some verifiable proof of official-ness (app attestation on iOS/Android, code-signing verification on desktop). Rejected for this draft: meaningfully more complex, and its security properties depend on platform attestation APIs this repo has no existing integration with. Bootstrap-seeding a native PKCE public client per instance (proposed above) reaches equivalent practical security (no secret to protect, redirect-URI scoped, and now per-instance revocable) for far less implementation risk.</li><li><strong>Per-instance admin opt-in toggle</strong> (a single Console switch — &quot;Allow official Sovereign apps&quot; — rather than always-on): a middle ground addressing the operator-control tradeoff above without per-client manual registration. Not adopted here; left open below rather than settled unilaterally, since it&#39;s a real operator-trust question, not just an implementation detail.</li></ul><h3 id="open-questions-1" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions-1" aria-label="Permalink to &quot;Open questions&quot;">​</a></h3><ul><li><strong>Confirmed still open, not merely hypothetical:</strong> <code>cachedTrustedClients</code> is not used (see point 2 above), so an operator who deletes a seeded client via Console gets it <strong>silently recreated</strong> on the next auth-server restart — <code>seedBuiltinOAuthClient</code> has no way to distinguish &quot;never created yet&quot; from &quot;created, then deliberately removed,&quot; since it only checks for a row matching the stable <code>name</code>. Not fixed in epic task 1.24; needs a persistence mechanism (e.g. a tombstone row, or an <code>auth_settings</code>-style marker) before this matters — i.e. before any real shell-side consumer exists and an operator could actually want to revoke one.</li><li>Should Console surface these two clients read-only, for operator visibility into what can authenticate against their instance, or not display them at all since there&#39;s nothing to configure?</li><li>Should there be an instance-level opt-out (see Alternatives), or is first-party-shell access always-on — the same category as the platform&#39;s own built-in Console/Launcher/Account plugins not being uninstallable?</li></ul><p><strong>Resolved:</strong> <code>sovereign-mobile</code>&#39;s redirect scheme (<code>sovereign://oauth/callback</code>, same as desktop) and the upgrade-window behavior of <code>GET /api/instance</code>&#39;s <code>oauthClients</code> field (omitted, not an error) — see points 2–3 above.</p><p>This addendum&#39;s seeding infrastructure (points 1–3) is implemented and live (epic task 1.24), but <strong>does not by itself unblock RFC 0082 §5 or sovereign-desktop epic task 17.4</strong> — those need the actual shell-side PKCE flow and OS keychain storage built against this, plus the remaining open questions above resolved, neither of which is scheduled yet.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>July 2026</td><td>Initial draft</td></tr><tr><td>0.2</td><td>July 2026</td><td>Implemented. Switched from the deprecated bundled <code>oidc-provider</code> to <code>@better-auth/oauth-provider</code>; corrected the custom-table assumption (plugin auto-manages its own schema); dropped the <code>tenant</code> claim (no multi-tenant concept in this platform); resolved both admin-gating open questions.</td></tr><tr><td>0.3</td><td>August 2026</td><td>Added the well-known first-party client addendum (draft, not implemented) — a design for <code>sovereign-desktop</code>/<code>sovereign-mobile</code> to authenticate as OAuth clients on arbitrary self-hosted instances without per-instance admin registration, proposed while scoping sovereign-desktop epic task 17.4 (blocked without it) and RFC 0082 §5&#39;s durable-session sketch.</td></tr><tr><td>0.4</td><td>August 2026</td><td>Corrected the addendum&#39;s mechanism against the actual installed <code>@better-auth/oauth-provider@1.6.25</code> package: <code>adminCreateOAuthClient</code> never accepts a caller-supplied <code>client_id</code>, so the &quot;two fixed literal IDs shared across every instance&quot; sketch in 0.3 doesn&#39;t work as written. Revised to per-instance bootstrap seeding (idempotent, using the already-shipped <code>adminCreateOAuthClient</code> — confirms no patching of the package is needed) plus a new <code>GET /api/instance</code> discovery field the shell reads to learn its generated ID. Net effect is a better security story than 0.3&#39;s (each instance&#39;s client is now independently revocable, not trusted unconditionally everywhere) at the cost of new open questions around deletion/recreation semantics and upgrade-window behavior. Still draft; still not implemented.</td></tr><tr><td>0.5</td><td>August 2026</td><td><strong>Partially implemented (epic task 1.24).</strong> Live-verified <code>adminCreateOAuthClient</code> itself doesn&#39;t work as 0.4 assumed — it&#39;s <code>SERVER_ONLY</code> but still requires a real user session internally, which doesn&#39;t exist at server boot — and corrected the mechanism to a direct <code>INSERT</code> into <code>oauthClient</code> instead, with the row shape reverse-engineered from a client created through the real admin path and confirmed to resolve via the same <code>getClient()</code> the authorize flow uses. Seeding (points 1–2) and <code>GET /api/instance</code> discovery (point 3) are shipped and live. Resolved the <code>sovereign-mobile</code> redirect-scheme and upgrade-window open questions. The revocation/recreation gap is now confirmed real, not hypothetical. The shell-side PKCE flow and OS keychain storage — the part that actually unblocks RFC 0082 §5 and sovereign-desktop epic task 17.4 — remains unbuilt and unscheduled.</td></tr></tbody></table>',59)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
